  "summary": "The customer called to change their expensive mobile plan to a cheaper one with more data. The agent processed the plan change request and took payment details, but the confirmation SMS was delayed, leaving the customer angry and dissatisfied at the end of the call.",
  "reasons": [
    {
      "evidence": [
        {
          "turn_id": 2,
          "quote": "mera plan change karna hai"
        }
      ],
      "label": "plan_change",
      "confidence": 1.0,
      "rationale": "The customer explicitly states they want to change their current plan."
    },
    {
      "evidence": [
        {
          "turn_id": 8,
          "quote": "network issues are also there. Signal bahut weak hai"
        }
      ],
      "label": "network",
      "confidence": 0.9,
      "rationale": "The customer mentions weak signal and network issues in their area."
    }
  ],
  "resolution": {
    "evidence": [
      {
        "turn_id": 13,
        "quote": "I'll ensure the plan is updated and the SMS is sent"
      }
    ],
    "status": "partial",
    "confidence": 0.9,
    "rationale": "The plan change request was processed, but the confirmation SMS was not yet received and the customer hung up angry, meaning the end-to-end task was not fully confirmed to the customer."
  },
  "churn": {
    "evidence": [
      {
        "turn_id": 14,
        "quote": "Your service is pathetic. I am very dissatisfied with this experience."
      }
    ],
    "risk_score": 0.4,
    "flag": false,
    "rationale": "The customer expressed intense anger and dissatisfaction with the service, but did not explicitly state an intention to cancel, switch providers, or port out."
  }
